#import <Foundation/Foundation.h>
#import "GDEngine.h"
#import <math.h>
static NSInteger checks=0;
static void Check(BOOL condition, NSString *message) { checks++;if(!condition){fprintf(stderr,"FAIL: %s\n",message.UTF8String);exit(1);} }
static GDCell *C(NSInteger r,NSInteger c,GDColor color){return [GDCell row:r column:c color:color];}
static NSSet *CellKeys(NSArray<GDCell *> *cells){NSMutableSet *keys=[NSMutableSet new];for(GDCell *cell in cells)[keys addObject:cell.key];return keys;}
static CGPoint P(NSValue *v){CGPoint p;[v getValue:&p];return p;}
static GDEngine *Fixture(NSArray *cells,GDColor color){GDEngine *e=[[GDEngine alloc]initWithSeed:20260930];[e loadFixture:cells phase:0 current:color next:GDColorWhite];return e;}
static GDShot *FindShot(GDEngine *engine, BOOL bounce, BOOL match) {
    for(NSInteger launcher=0;launcher<3;launcher++){[engine selectLauncher:launcher];for(NSInteger x=-1500;x<=2300;x+=5){GDShot *s=[engine previewToward:CGPointMake(x,0)];if(s.valid&&(!bounce||s.bounced)&&(!match||s.expectedMatches.count>=3))return s;}}return nil;
}
static void Finish(GDEngine *engine){for(NSInteger i=0;i<40&&engine.phase==GDPhaseResolving;i++)[engine finishResolution];}
static GDEvent *Fire(GDEngine *e,BOOL match){GDShot *s=FindShot(e,NO,match);Check(s!=nil,@"fixture has intended shot");Check([e beginShot:s],@"fixture fire accepted");GDEvent *event=[e resolveShot];Check(event!=nil,@"fixture resolved");return event;}
static void BasicAndGeometry(void){
