    GDEngine *same=[[GDEngine alloc]initWithSeed:20260930];Check([e.snapshot[@"board"] isEqual:same.snapshot[@"board"]],@"seed reproduces opening");
    GDShot *shot=FindShot(e,NO,NO);Check(shot!=nil,@"opening reachable");GDColor next=e.nextColor;CGPoint predicted=P(shot.points.lastObject);Check([e beginShot:shot],@"valid shot accepted");Check(![e beginShot:shot],@"duplicate shot rejected");Check(![e hold]&&![e selectLauncher:0],@"flight locks queue and launcher");
