    shot=FindShot(e,YES,NO);Check(shot!=nil,@"one bounce shot available");Check(shot.points.count>=4,@"bounce and landing path exposed");Check([e beginShot:shot],@"bounce accepted");event=[e resolveShot];Check(event.placed.row==shot.landingRow&&event.placed.column==shot.landingColumn,@"bounce prediction equals result");Finish(e);
    NSArray *before=e.cells;NSMutableDictionary *positions=[NSMutableDictionary new],*links=[NSMutableDictionary new];for(GDCell *c in before){positions[c.key]=[NSValue valueWithPoint:NSMakePoint([e centerOfCell:c].x,[e centerOfCell:c].y)];NSMutableSet *keys=[NSMutableSet new];for(GDCell *n in [e neighborsOfCell:c])[keys addObject:n.key];links[c.key]=keys;}
    event=[e advanceTime:12];Check(event.pushed,@"timer pushes row");for(GDCell *c in before){GDCell *shift=C(c.row+1,c.column,c.color);CGPoint old=[positions[c.key] pointValue],p=[e centerOfCell:shift];Check(fabs(old.x-p.x)<.001&&fabs(p.y-old.y-23*sqrt(3))<.001,@"pressure preserves x and spacing");NSMutableSet *oldLinks=links[c.key];NSMutableSet *newLinks=[NSMutableSet new];for(GDCell *n in [e neighborsOfCell:shift])if(n.row>0)[newLinks addObject:[NSString stringWithFormat:@"%ld:%ld",(long)n.row-1,(long)n.column]];Check([oldLinks isEqual:newLinks],@"pressure preserves old adjacency");}Finish(e);
