    NSLog(@"Dense angle sweep valid=%ld/%ld direct=%ld targets L/C/R=%lu/%lu/%lu",(long)valid,(long)total,(long)directValid,(unsigned long)[launchSets[0] count],(unsigned long)[launchSets[1] count],(unsigned long)[launchSets[2] count]);Check(valid>total*.55&&directValid>100,@"broad oblique/straight shots remain playable");Check(![launchSets[0] isEqual:launchSets[1]],@"launcher changes reachable grid targets");
