    for(NSInteger launcher=0;launcher<3;launcher++){[g selectLauncher:launcher];for(NSInteger x=-800;x<1600;x+=20){GDShot *s=[g previewToward:CGPointMake(x,0)];Check(!(s.valid&&s.landingRow==2&&s.landingColumn==8),@"sealed interior never reachable");}}
    // No-width rays would pass between tangent candies; projectile radius must hit first.
    g=Fixture(@[C(0,8,GDColorRed),C(0,9,GDColorYellow)],GDColorBlue);[g selectLauncher:1];shot=[g previewToward:CGPointMake(414,0)];Check(shot.hitCell!=nil,@"finite projectile hits two-candy gap");
