    NSMutableArray *sweepBoard=[NSMutableArray new],*expectedSweep=[NSMutableArray new];for(NSInteger row=0;row<7;row++)for(NSNumber *column in @[@0,@8]){GDCell *cell=C(row,column.integerValue,row%4);[sweepBoard addObject:cell];if(row>=3)[expectedSweep addObject:cell];}e=Fixture(sweepBoard,GDColorBlue);[e setFixtureEnergy:@[@0,@0,@20,@0]];NSArray *targets=e.yellowTargets;Check([CellKeys(targets) isEqual:CellKeys(expectedSweep)],@"yellow targets exactly the deepest four rows across columns");event=[e activateYellow];Check(event.source==GDSourceYellow&&[CellKeys(event.removed) isEqual:CellKeys(targets)]&&event.fallen.count==0&&e.cells.count==6,@"yellow preview matches removal and preserves the upper rows");Check(e.score==80&&[e.energy[0] integerValue]==0&&[e.energy[1] integerValue]==0&&[e.energy[2] integerValue]==0,@"yellow scores once without energy refund");Check(![e activateYellow],@"yellow cannot double spend");Finish(e);
    e=Fixture(@[C(0,0,GDColorRed),C(1,0,GDColorRed),C(2,0,GDColorBlue),C(3,0,GDColorYellow),C(6,8,GDColorWhite)],GDColorBlue);Check([CellKeys(e.yellowTargets) isEqual:[NSSet setWithArray:@[@"3:0",@"6:8"]]],@"yellow uses four grid rows even with empty rows in the bottom window");
