static void FiveWildShotsAndEndlessCosts(void){
    GDEngine *e=Fixture(EnergyFixture(),GDColorRed);[e setFixtureEnergy:@[@0,@0,@0,@20]];
    Check([e activateSkill:GDColorWhite]&&e.wildRemaining==5&&[e energyThresholdForColor:GDColorWhite]==21,@"one white skill grants five shots and raises only its next cost");
    for(NSInteger shotIndex=0;shotIndex<5;shotIndex++){
        GDColor color=shotIndex%4;[e loadFixture:@[C(0,0,GDColorWhite),C(0,8,color),C(0,9,color)] phase:0 current:(color+1)%4 next:GDColorWhite];
        GDEvent *event=Fire(e,YES);Check(event.source==GDSourceWild&&event.placed.color==color&&event.removed.count==3&&e.wildRemaining==4-shotIndex,@"each of the five wild shots adapts to any adjacent color");
        Check([e.energy isEqual:@[@0,@0,@0,@0]]&&[e energyThresholdForColor:GDColorWhite]==21,@"wild shots neither refund energy nor increase skill cost again");Finish(e);
    }
    [e loadFixture:EnergyFixture() phase:0 current:GDColorBlue next:GDColorWhite];GDEvent *event=Fire(e,YES);Check(event.source==GDSourceNormal&&e.energy[GDColorBlue].integerValue==3,@"sixth shot returns to normal matching and charging");Finish(e);
    [e setFixtureEnergy:@[@0,@0,@0,@20]];Check(![e activateSkill:GDColorWhite]&&[e energyThresholdForColor:GDColorWhite]==21,@"twenty energy cannot reactivate a skill whose next cost is twenty-one");
    [e setFixtureEnergy:@[@0,@0,@0,@21]];Check([e activateSkill:GDColorWhite]&&e.wildRemaining==5&&[e energyThresholdForColor:GDColorWhite]==22,@"second white use costs twenty-one and raises the next cost to twenty-two");
    GDEngine *restored=[[GDEngine alloc]initWithSnapshot:e.snapshot];Check(restored!=nil&&restored.wildRemaining==5&&[restored energyThresholdForColor:GDColorWhite]==22,@"five wild shots and increased costs survive cold restore");
    [e setFixtureEnergy:@[@0,@0,@0,@22]];Check(![e activateSkill:GDColorWhite]&&[e energyThresholdForColor:GDColorWhite]==22,@"active white effect cannot be stacked or charged another use");

    e=Fixture(EnergyFixture(),GDColorBlue);[e setFixtureEnergy:@[@20,@20,@20,@20]];
    Check([e activateSkill:GDColorBlue]&&[e energyThresholdForColor:GDColorBlue]==21&&[e energyThresholdForColor:GDColorRed]==20&&[e energyThresholdForColor:GDColorYellow]==20&&[e energyThresholdForColor:GDColorWhite]==20,@"blue raises its cost independently of the other three colors");
    [e setFixtureEnergy:@[@21,@20,@20,@20]];Check(![e activateSkill:GDColorBlue]&&[e energyThresholdForColor:GDColorBlue]==21,@"active freeze rejects another use without raising its cost");
    Check([e activateSkill:GDColorWhite]&&[e energyThresholdForColor:GDColorWhite]==21,@"white activation increments once while other skills are active");
    Check([e activateSkill:GDColorRed]&&[e energyThresholdForColor:GDColorRed]==20,@"red arming does not increase its cost");[e cancelBlast];Check([e energyThresholdForColor:GDColorRed]==20&&e.energy[GDColorRed].integerValue==20,@"red cancellation preserves cost and energy");
    [e activateSkill:GDColorRed];GDShot *shot=FindShot(e,NO,NO);Check([e beginShot:shot]&&[e energyThresholdForColor:GDColorRed]==21,@"red raises its cost only after an accepted launch");
    restored=[[GDEngine alloc]initWithSnapshot:e.snapshot];Check(restored!=nil&&[restored energyThresholdForColor:GDColorRed]==20&&restored.energy[GDColorRed].integerValue==20&&restored.wildRemaining==5,@"interrupted red flight refunds both energy and the use that increased cost");
    [e resolveShot];Finish(e);restored=[[GDEngine alloc]initWithSnapshot:e.snapshot];Check(restored!=nil&&[restored energyThresholdForColor:GDColorRed]==21&&restored.energy[GDColorRed].integerValue==0,@"committed red blast preserves the increased cost on restore");
    e=Fixture(@[],GDColorBlue);[e setFixtureEnergy:@[@0,@20,@20,@0]];Check(![e activateYellow]&&[e energyThresholdForColor:GDColorYellow]==20,@"empty yellow use does not increase cost");[e activateSkill:GDColorRed];shot=[e previewToward:CGPointMake(414,0)];Check(![e beginShot:shot]&&[e energyThresholdForColor:GDColorRed]==20,@"invalid red launch does not increase cost");

    e=Fixture(@[C(0,0,GDColorYellow)],GDColorBlue);
    for(NSInteger uses=0;uses<35;uses++){
        NSInteger cost=MIN(20+uses,50);[e loadFixture:@[C(0,0,GDColorYellow)] phase:0 current:GDColorBlue next:GDColorWhite];[e setFixtureEnergy:@[@0,@0,@(cost),@0]];
        Check([e energyThresholdForColor:GDColorYellow]==cost&&[e activateYellow]!=nil,@"yellow charges the increased cost on each consecutive use");Finish(e);
        Check(e.energy[GDColorYellow].integerValue==0&&[e energyThresholdForColor:GDColorYellow]==MIN(21+uses,50),@"new waves retain cost growth and the fifty-energy cap");
    }
    Check([e energyThresholdForColor:GDColorBlue]==20&&[e energyThresholdForColor:GDColorRed]==20&&[e energyThresholdForColor:GDColorWhite]==20,@"thirty-five yellow uses never change the other colors' costs");
    restored=[[GDEngine alloc]initWithSnapshot:e.snapshot];Check(restored!=nil&&[restored energyThresholdForColor:GDColorYellow]==50,@"capped skill cost persists exactly");
    [e loadFixture:@[C(0,0,GDColorRed),C(0,8,GDColorYellow),C(0,9,GDColorYellow)] phase:0 current:GDColorYellow next:GDColorBlue];[e setFixtureEnergy:@[@0,@0,@49,@0]];event=Fire(e,YES);Check(e.energy[GDColorYellow].integerValue==50&&[e energyThresholdForColor:GDColorYellow]==50,@"normal matching can charge above twenty and clamps at fifty");Finish(e);
    Check([[[GDEngine alloc]initWithSeed:1] energyThresholdForColor:GDColorYellow]==20,@"new endless run resets all skill prices");
    NSMutableDictionary *snapshot=[e.snapshot mutableCopy];snapshot[@"energy"]=@[@0,@0,@51,@0];Check(![[GDEngine alloc]initWithSnapshot:snapshot],@"restore rejects energy above the current capped threshold");
    e=Fixture(EnergyFixture(),GDColorBlue);snapshot=[e.snapshot mutableCopy];snapshot[@"stats"]=@{@"blueUses":@5};snapshot[@"energy"]=@[@23,@0,@0,@0];e=[[GDEngine alloc]initWithSnapshot:snapshot];[e resume];event=Fire(e,YES);Check(e.energy[GDColorBlue].integerValue==25&&[e energyThresholdForColor:GDColorBlue]==25&&[e.diagnostics[@"stats"][@"energy0Full"] integerValue]==1,@"charging respects the restored per-color threshold and credits ready once");
    snapshot=[e.snapshot mutableCopy];snapshot[@"wild"]=@6;Check(![[GDEngine alloc]initWithSnapshot:snapshot],@"restore rejects more than five wild shots");snapshot[@"wild"]=@3;snapshot[@"stats"]=@{};snapshot[@"energy"]=@[@20,@20,@20,@20];restored=[[GDEngine alloc]initWithSnapshot:snapshot];Check(restored!=nil&&restored.wildRemaining==3&&[restored energyThresholdForColor:GDColorWhite]==20,@"legacy remaining wild shots and missing use counters remain compatible");

    for(GDColor color=GDColorBlue;color<=GDColorWhite;color++){
        GDEngine *level=[[GDEngine alloc]initWithLevelID:4 seed:1];snapshot=[level.snapshot mutableCopy];snapshot[@"stats"]=@{@"blueUses":@40,@"redUses":@40,@"yellowUses":@40,@"whiteUses":@40};snapshot[@"energy"]=@[@20,@20,@20,@20];level=[[GDEngine alloc]initWithSnapshot:snapshot];[level resume];
        BOOL used=color==GDColorYellow?[level activateYellow]!=nil:[level activateSkill:color];if(color==GDColorRed){shot=FindShot(level,NO,NO);used=[level beginShot:shot];[level resolveShot];}
        Check(used&&[level energyThresholdForColor:color]==20,@"campaign skills retain fixed twenty-energy costs after repeated uses");
    }
    NSLog(@"PASS: five wild shots, per-color endless costs, charging, cancellation, cap and restore");
}
