    e=[[GDEngine alloc]initWithSeed:5];NSTimeInterval left=e.pressureRemaining;[e pause];[e advanceTime:1000];Check(e.pressureRemaining==left&&e.elapsed==0,@"paused background time never counts");[e resume];Check(e.phase==GDPhaseReady,@"resume restores stable phase");
    e=Fixture(EnergyFixture(),GDColorBlue);[e setFixtureEnergy:@[@0,@20,@0,@20]];[e activateSkill:GDColorWhite];[e activateSkill:GDColorRed];shot=FindShot(e,NO,NO);NSDictionary *before=e.snapshot;[e beginShot:shot];[e advanceTime:3];[e pause];GDEngine *restored=[[GDEngine alloc]initWithSnapshot:e.snapshot];Check(restored!=nil&&restored.phase==GDPhasePaused,@"flight restore paused stable checkpoint");Check([restored.snapshot[@"board"] isEqual:before[@"board"]]&&restored.wildRemaining==5&&[restored.energy[1] integerValue]==20&&restored.elapsed==[before[@"elapsed"] doubleValue],@"interrupted unlanded shot refunds blast wild and flight time");[e resume];Check(e.phase==GDPhaseFlying,@"in-memory resume preserves flight");event=[e resolveShot];Check(event.source==GDSourceBlast,@"in-memory flight completes once");Finish(e);
    e=[[GDEngine alloc]initWithSeed:3];shot=FindShot(e,NO,NO);[e beginShot:shot];[e advanceTime:12];[e resolveShot];NSInteger score=e.score;NSArray *committed=e.snapshot[@"board"];restored=[[GDEngine alloc]initWithSnapshot:e.snapshot];[restored resume];Check(restored.pressurePending&&restored.score==score&&[restored.snapshot[@"board"] isEqual:committed],@"settled checkpoint retains committed result and pressure");Check(![restored hold]&&![restored activateSkill:GDColorBlue],@"due pressure blocks input immediately after restore");shot=[restored previewToward:CGPointMake(414,0)];Check(!shot.valid&&![restored beginShot:shot],@"due pressure blocks fire before first tick");event=[restored advanceTime:0];Check(event.pushed,@"restored due pressure executes first");Finish(restored);
    e=[[GDEngine alloc]initWithSeed:6];[e setFixtureEnergy:@[@20,@0,@0,@0]];[e activateSkill:GDColorBlue];restored=[[GDEngine alloc]initWithSnapshot:e.snapshot];Check(restored!=nil&&restored.freezeRemaining==30,@"full thirty-second freeze restores");[e advanceTime:2];restored=[[GDEngine alloc]initWithSnapshot:e.snapshot];Check(restored.freezeRemaining==28&&restored.pressureRemaining==12,@"freeze state persists exact remaining");[restored advanceTime:100];Check(restored.freezeRemaining==28,@"restored paused freeze does not expire");[restored resume];[restored advanceTime:28];Check(restored.freezeRemaining==0&&restored.pressureRemaining==12,@"restored freeze resumes fairly");NSMutableDictionary *freezeSnapshot=[e.snapshot mutableCopy];freezeSnapshot[@"freeze"]=@6;Check([[GDEngine alloc]initWithSnapshot:freezeSnapshot].freezeRemaining==6,@"legacy six-second freeze remains compatible");freezeSnapshot[@"freeze"]=@31;Check(![[GDEngine alloc]initWithSnapshot:freezeSnapshot],@"freeze above thirty seconds is rejected");
    // Failure uses the edge, not center; fallen pieces are already removed.
    e=Fixture(@[C(0,8,GDColorRed),C(1,8,GDColorRed),C(2,8,GDColorRed),C(3,8,GDColorRed),C(4,8,GDColorRed),C(5,8,GDColorRed),C(6,8,GDColorRed),C(7,8,GDColorRed),C(8,8,GDColorRed),C(9,8,GDColorRed)],GDColorBlue);event=[e advanceTime:12];Check(event.gameOver&&e.phase==GDPhaseGameOver,@"pressure edge-crossing ends run");Check(![e hold]&&![e activateSkill:GDColorRed]&&[e advanceTime:50]==nil,@"failure rejects input and time");
    Check([[GDEngine alloc]initWithSnapshot:@{@"format":@1}]==nil,@"malformed snapshot rejected");
}
static void RandomLongRuns(void){
    NSInteger accepted=0,bounces=0;
    for(NSUInteger seed=1;seed<=24;seed++){
        GDEngine *e=[[GDEngine alloc]initWithSeed:seed];
        for(NSInteger step=0;step<160&&e.phase!=GDPhaseGameOver;step++){
            if(step%7==0)[e hold];if(step%9==0)[e selectLauncher:step%3];
            if([e.energy[0] integerValue]==[e energyThresholdForColor:GDColorBlue])[e activateSkill:GDColorBlue];if([e.energy[3] integerValue]==[e energyThresholdForColor:GDColorWhite])[e activateSkill:GDColorWhite];
            if([e.energy[2] integerValue]==[e energyThresholdForColor:GDColorYellow]){[e activateYellow];Finish(e);}
            if([e.energy[1] integerValue]==[e energyThresholdForColor:GDColorRed])[e activateSkill:GDColorRed];
            if(e.phase!=GDPhaseReady)break;GDShot *shot=FindShot(e,step%5==0,step%3==0);if(!shot)shot=FindShot(e,NO,NO);if(!shot){[e advanceTime:12];Finish(e);continue;}
            bounces+=shot.bounced;Check([e beginShot:shot],@"random accepted preview");[e advanceTime:.4];GDEvent *event=[e resolveShot];accepted++;Check(event!=nil,@"random shot resolves");NSMutableSet *keys=[NSMutableSet new];for(GDCell *c in [event.removed arrayByAddingObjectsFromArray:event.fallen]){Check(![keys containsObject:c.key],@"event counts each tile once");[keys addObject:c.key];}Finish(e);[e advanceTime:.6];Finish(e);
            NSMutableSet *occupied=[NSMutableSet new];for(GDCell *c in e.cells){Check(![occupied containsObject:c.key],@"one occupant per cell");[occupied addObject:c.key];}
            for(GDColor color=GDColorBlue;color<=GDColorWhite;color++)Check(e.energy[color].integerValue>=0&&e.energy[color].integerValue<=[e energyThresholdForColor:color],@"energy bounded by the color threshold");
        }
    }
    NSLog(@"Random seed audit: 24 seeds, %ld accepted shots, %ld bounced",(long)accepted,(long)bounces);Check(accepted>150&&bounces>10,@"representative deterministic long runs");
}
int main(int argc,const char *argv[]){@autoreleasepool{
    BOOL focused=argc>1&&strcmp(argv[1],"--focused")==0;
    BasicAndGeometry();NSLog(@"PASS: geometry, density, prediction and bounce fixtures");
    MatchingEnergyAndSkills();NSLog(@"PASS: matching, support, energy and four skills fixtures");
    FiveWildShotsAndEndlessCosts();
    QueueTimersPersistence();NSLog(@"PASS: queue, pressure priority, pause and cold-restore fixtures");
    if(!focused)RandomLongRuns();
    NSLog(@"PASS: %@ core validation (%ld assertions)",focused?@"focused":@"full 24-seed",(long)checks);
}}
